#include <iostream>
#include <sstream>
#include <string>
#include <vector>

struct Recuento {
    int aceptados;
    int rechazados;
};

bool recuento_valido(const Recuento& valor) {
    return valor.aceptados >= 0 && valor.aceptados <= 10
        && valor.rechazados >= 0 && valor.rechazados <= 10;
}

std::istream& operator>>(std::istream& origen, Recuento& destino) {
    char apertura{0};
    char separador{0};
    char cierre{0};
    Recuento candidato{0, 0};
    if (!(origen >> apertura >> candidato.aceptados >> separador
          >> candidato.rechazados >> cierre)) {
        return origen;
    }
    if (apertura != '[' || separador != ';' || cierre != ']'
        || !recuento_valido(candidato)) {
        origen.setstate(std::ios::failbit);
        return origen;
    }
    destino = candidato;
    return origen;
}

struct Registro {
    int id;
    Recuento recuento;
};

bool leer_linea(const std::string& linea, Registro& destino) {
    std::istringstream origen{linea};
    Registro candidato{0, {0, 0}};
    if (!(origen >> candidato.id >> candidato.recuento)
        || candidato.id < 0 || candidato.id > 9) {
        return false;
    }
    origen >> std::ws;
    if (!origen.eof() || origen.bad()) {
        return false;
    }
    destino = candidato;
    return true;
}

int main() {
    const std::vector<std::string> pruebas{
        "3 [2;1]", "3 [2;1] reste", "10 [2;1]", "3 [2;11]"
    };
    for (const std::string& linea : pruebas) {
        Registro destino{8, {9, 9}};
        bool valido = leer_linea(linea, destino);
        std::cout << valido << ':' << destino.id << ':'
                  << destino.recuento.aceptados << ':'
                  << destino.recuento.rechazados << '\n';
    }
    return 0;
}
